pub struct rtas_fn_handle_t { pub index: rtas_function_index }
pub const fn rtas_fn_handle(index: rtas_function_index) -> rtas_fn_handle_t { rtas_fn_handle_t { index } }

/* Build-time RTAS function handles. */
macro_rules! rtas_handles { ($($n:ident => $i:ident),* $(,)?) => { $(pub const $n: rtas_fn_handle_t = rtas_fn_handle(rtas_function_index::$i);)* }; }
