/* Kernel-provided declarations retained as opaque external types. */
#[repr(C)] pub struct rtas_t { _private: [u8;0] }
#[repr(C)] pub struct rtas_error_log { pub byte1:u8, pub byte2:u8, pub byte3:u8, pub extended_log_length:u32 }
#[repr(C)] pub struct pseries_errorlog { pub id:u16, pub length:u16 }
#[repr(C)] pub struct spinlock_t { _private:[u8;0] }

